/// @brief Enumeration for Intelligent Network Monitoring (INM) error code.
/// @since_tizen 5.0
abstract class inm_error_e {
  /// Successful
  static const int INM_ERROR_NONE = 0;

  /// Operation not permitted(1)
  static const int INM_ERROR_NOT_PERMITTED = -1;

  /// Out of memory(12)
  static const int INM_ERROR_OUT_OF_MEMORY = -12;

  /// Permission denied(13)
  static const int INM_ERROR_PERMISSION_DENIED = -13;

  /// Device or resource busy(16)
  static const int INM_ERROR_RESOURCE_BUSY = -16;

  /// Invalid function parameter(22)
  static const int INM_ERROR_INVALID_PARAMETER = -22;

  /// Connection timed out(110)
  static const int INM_ERROR_CONNECTION_TIME_OUT = -110;

  /// Now in progress(115)
  static const int INM_ERROR_NOW_IN_PROGRESS = -115;

  /// Not supported
  static const int INM_ERROR_NOT_SUPPORTED = -1073741822;

  /// Not initialized
  static const int INM_ERROR_NOT_INITIALIZED = -50200575;

  /// Already initialized
  static const int INM_ERROR_ALREADY_INITIALIZED = -50200574;

  /// Operation failed
  static const int INM_ERROR_OPERATION_FAILED = -50200573;

  /// Data not found
  static const int INM_ERROR_DATA_NOT_FOUND = -50200572;
}

