/// @brief Enumeration for Wi-Fi disconnect reason, provided by the supplicant.
/// @since_tizen 5.0
abstract class inm_wifi_disconnect_reason_e {
  /// Locally Generate Disconnect from user side
  static const int INM_WIFI_REASON_LOCAL_GENERATE_FROM_USER = -3;

  /// Unspecified reason
  static const int INM_WIFI_REASON_UNSPECIFIED = 1;

  /// Previous authentication no longer valid
  static const int INM_WIFI_REASON_PREV_AUTH_NOT_VALID = 2;

  /// Deauthenticated because sending STA is leaving (or has left) IBSS or ESS
  static const int INM_WIFI_REASON_DEAUTH_LEAVING = 3;

  /// Disassociated due to inactivity
  static const int INM_WIFI_REASON_DISASSOC_DUE_TO_INACTIVITY = 4;

  /// Disassociated because AP is unable to handle all currently associated STAs
  static const int INM_WIFI_REASON_DISASSOC_AP_BUSY = 5;

  /// Class 2 frame received from nonauthenticated STA
  static const int INM_WIFI_REASON_CLASS2_FRAME_FROM_NONAUTH_STA = 6;

  /// Class 3 frame received from nonassociated STA
  static const int INM_WIFI_REASON_CLASS3_FRAME_FROM_NONASSOC_STA = 7;

  /// Disassociated because sending STA is leaving (or has left) BSS
  static const int INM_WIFI_REASON_DISASSOC_STA_HAS_LEFT = 8;

  /// STA requesting (re)association is not authenticated with responding STA
  static const int INM_WIFI_REASON_STA_REQ_ASSOC_WITHOUT_AUTH = 9;

  /// Disassociated because the information in the Power Capability
  /// element is unacceptable
  static const int INM_WIFI_REASON_PWR_CAPABILITY_NOT_VALID = 10;

  /// Disassociated because the information in the Supported Channels
  /// element is unacceptable
  static const int INM_WIFI_REASON_SUPPORTED_CHANNEL_NOT_VALID = 11;

  /// Invalid element i.e., an element defined in this standard for which the
  /// content does not meet the specifications in Clause 8
  static const int INM_WIFI_REASON_INVALID_IE = 13;

  /// Message Integrity Code (MIC) failure
  static const int INM_WIFI_REASON_MICHAEL_MIC_FAILURE = 14;

  /// 4-Way Handshake timeout
  static const int INM_WIFI_REASON_4WAY_HANDSHAKE_TIMEOUT = 15;

  /// Group Key Handshake timeout
  static const int INM_WIFI_REASON_GROUP_KEY_UPDATE_TIMEOUT = 16;

  /// Element in 4-Way Handshake different from (Re)Association Request/Probe
  /// Response/Beacon frame
  static const int INM_WIFI_REASON_IE_IN_4WAY_DIFFERS = 17;

  /// Invalid group cipher
  static const int INM_WIFI_REASON_GROUP_CIPHER_NOT_VALID = 18;

  /// Invalid pairwise cipher
  static const int INM_WIFI_REASON_PAIRWISE_CIPHER_NOT_VALID = 19;

  /// Invalid AKMP
  static const int INM_WIFI_REASON_AKMP_NOT_VALID = 20;

  /// Unsupported RSNE version
  static const int INM_WIFI_REASON_UNSUPPORTED_RSN_IE_VERSION = 21;

  /// Invalid RSNE capabilities
  static const int INM_WIFI_REASON_INVALID_RSN_IE_CAPAB = 22;

  /// IEEE 802.1X authentication failed
  static const int INM_WIFI_REASON_IEEE_802_1X_AUTH_FAILED = 23;

  /// Cipher suite rejected because of the security policy
  static const int INM_WIFI_REASON_CIPHER_SUITE_REJECTED = 24;

  /// TDLS direct-link teardown due to TDLS peer STA unreachable via the
  /// TDLS direct link
  static const int INM_WIFI_REASON_TDLS_TEARDOWN_UNREACHABLE = 25;

  /// TDLS direct-link teardown for unspecified reason
  static const int INM_WIFI_REASON_TDLS_TEARDOWN_UNSPECIFIED = 26;

  /// Disassociated because excessive number of frames need to be acknowledged,
  /// but are not acknowledged due to AP transmissions and/or poor channel conditions
  static const int INM_WIFI_REASON_DISASSOC_LOW_ACK = 34;

  /// SME cancels the mesh peering instance with the reason other than reaching
  /// the maximum number of peer mesh STAs
  static const int INM_WIFI_REASON_MESH_PEERING_CANCELLED = 52;

  /// The mesh STA has reached the supported maximum number of peer mesh STAs
  static const int INM_WIFI_REASON_MESH_MAX_PEERS = 53;

  /// The received information violates the Mesh Configuration policy
  /// configured in the mesh STA profile
  static const int INM_WIFI_REASON_MESH_CONFIG_POLICY_VIOLATION = 54;

  /// The mesh STA has received a Mesh Peering Close message requesting
  /// to close the mesh peering
  static const int INM_WIFI_REASON_MESH_CLOSE_RCVD = 55;

  /// The mesh STA has resent dot11MeshMaxRetries Mesh Peering Open messages,
  /// without receiving a Mesh Peering Confirm message
  static const int INM_WIFI_REASON_MESH_MAX_RETRIES = 56;

  /// The confirmTimer for the mesh peering instance times out
  static const int INM_WIFI_REASON_MESH_CONFIRM_TIMEOUT = 57;

  /// The mesh STA fails to unwrap the GTK or the values in the wrapped
  /// contents do not match
  static const int INM_WIFI_REASON_MESH_INVALID_GTK = 58;

  /// The mesh STA receives inconsistent information about the mesh parameters
  /// between Mesh Peering Management frames
  static const int INM_WIFI_REASON_MESH_INCONSISTENT_PARAMS = 59;

  /// The mesh STA does not have proxy information for this external destination
  static const int INM_WIFI_REASON_MESH_INVALID_SECURITY_CAP = 60;
}

